/// <summary>
/// UI Builder for METDutyRollMonthly
/// </summary>
internal final class METDutyRollMonthlyUIBuilder extends SysOperationAutomaticUIBuilder
{
    METDutyRollMonthlyContract  contract;
    DialogField                 adHocDF; 
    DialogField                 itemsQueryDF;
    DialogField                 sitesListDF;
    DialogField                 runForExciseDF;
    DialogField                 immediateChange; //C-Added for the FSD-CB799
    container                   conContainer;
    DialogField                 effectiveDateDF;
    DialogField                 cpiDF;

}

Method.Source:
    /// <summary>
    /// Maps dialog fields above to contract method
    /// </summary>
    public void postBuild()
    {
        super();
        
        contract = this.dataContractObject() as METDutyRollMonthlyContract;

        itemsQueryDF    = this.bindInfo().getDialogField(contract, methodStr(METDutyRollMonthlyContract, parmItemList));
        itemsQueryDF.lookupButton(FormLookupButton::Always);
        
        sitesListDF     = this.bindInfo().getDialogField(contract, methodStr(METDutyRollMonthlyContract, parmSiteList));
        sitesListDF.lookupButton(FormLookupButton::Always);
        adHocDF         = this.bindInfo().getDialogField(contract, methodStr(METDutyRollMonthlyContract, parmAdHoc));
        runForExciseDF  = this.bindInfo().getDialogField(contract, methodStr(METDutyRollMonthlyContract, parmRunForExcise));
        immediateChange = this.bindInfo().getDialogField(contract, methodStr(METDutyRollMonthlyContract, parmImmediateChange));
        effectiveDateDF = this.bindInfo().getDialogField(contract, methodStr(METDutyRollMonthlyContract, parmEffectiveDate));
        cpiDF          = this.bindInfo().getDialogField(contract, methodStr(METDutyRollMonthlyContract, parmCpi));
        adHocDF.visible(false);
        immediateChange.visible(false);
    }

    /// <summary>
    /// Item lookup
    /// </summary>
    /// <param name = "_formStringControl">dialog field</param>
    public void itemLookup(FormStringControl    _formStringControl)
    {
        const   str             tariffCodeC = "@MET:TariffCodeC";
        const   str             tariffCodeE = "@MET:TariffCodeE";
        Query                   query = new Query(queryStr(METInventTableTariffItemCode));
        QueryBuildDataSource    metTariffItemCodeQbds;
        QueryBuildRange         qbr;

        metTariffItemCodeQbds = query.dataSourceTable(tableNum(METTariffItemCodeBase));
        
        metTariffItemCodeQbds.clearRange(fieldNum(METTariffItemCodeBase, CustomsExcise));
        
        if (runForExciseDF.value() == NoYes::Yes && !cpiDF.value())
        {
            qbr = metTariffItemCodeQbds.addRange(fieldNum(METTariffItemCodeBase, CustomsExcise));
            qbr.value(queryValue(tariffCodeE));
        }
        
        
        SysLookupMultiSelectGrid::lookup(query,
                                         _formStringControl,
                                         _formStringControl,
                                         _formStringControl,
                                         conContainer);
        
        this.itemModified(_formStringControl);
    }

    /// <summary>
    /// Site lookup
    /// </summary>
    /// <param name = "_formStringControl">dialog field</param>
    public void sitelookup(FormStringControl    _formStringControl)
    {
        Query                   query = new Query();
        QueryBuildDataSource    queryBuildDataSource;

        queryBuildDataSource =   query.addDataSource(tableNum(InventSite));
        queryBuildDataSource.addSelectionField(fieldNum(InventSite, SiteId));
        queryBuildDataSource.addSelectionField(fieldNum(InventSite, Name));

        SysLookupMultiSelectGrid::lookup(query,
                                         _formStringControl,
                                         _formStringControl,
                                         _formStringControl,
                                         conContainer);
    }

/// <summary>
/// Handles the UI modified event for the item query dialog field.
/// </summary>
/// <param name="_control">
/// The control behind the changed dialog field.
/// </param>
/// <returns>
/// true if the control value has been modified; otherwise, false.
/// </returns>
public boolean itemModified(FormStringControl _control)
{
    boolean ret = _control.modified();
    if(ret)
    {
        if (itemsQueryDF.value())
        {
            runForExciseDF.allowEdit(false);
        }
        else
        {
            runForExciseDF.allowEdit(true);
        }
    }
    return ret;
}

    /// <summary>
    /// Super needs to be commencted out or we receive errors
    /// </summary>
    public void postRun()
    {
        FormStringControl   itemControl = itemsQueryDF.control();

        itemControl.lookupOnly(true);

        itemsQueryDF.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METDutyRollMonthlyUIBuilder, itemLookup), this);
        itemsQueryDF.registerOverrideMethod(methodStr(FormStringControl, modified), methodStr(METDutyRollMonthlyUIBuilder, itemModified), this);
        sitesListDF.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METDutyRollMonthlyUIBuilder, sitelookup), this);
        cpiDF.registerOverrideMethod(methodStr(FormCheckBoxControl, modified), methodStr(METDutyRollMonthlyUIBuilder, cpiModified), this);
        effectiveDateDF.registerOverrideMethod(methodStr(FormDateControl, modified), methodStr(METDutyRollMonthlyUIBuilder, effectiveDateModified), this);
    }

/// <summary>
/// Handles the UI modified event for the CPI dialog field.
/// </summary>
/// <param name="_control">The control behind the changed dialog field.</param>
/// <returns>true if the control value has been modified; otherwise, false.</returns>
public boolean cpiModified(FormCheckBoxControl _control)
{
    boolean ret = _control.modified();
    if (ret)
    {
        if (cpiDF.value() == NoYes::Yes)
        {
            runForExciseDF.value(NoYes::No);
            runForExciseDF.allowEdit(false);
        }
        else
        {
            runForExciseDF.allowEdit(true);
        }
    }
    return ret;
}

/// <summary>
/// Handles the UI modified event for the effective date dialog field.
/// </summary>
/// <param name="_control">The control behind the changed dialog field.</param>
/// <returns>true if the control value has been modified; otherwise, false.</returns>
public boolean effectiveDateModified(FormDateControl _control)
{
    boolean ret = _control.modified();
    if (ret)
    {
        // Effective date cannot be in the past. Please select today or future date.
        if (_control.dateValue() < DateTimeUtil::date(DateTimeUtil::utcNow()))
        {
            ret = false;
            error("@MET:EffectiveDateCannotBeInThePast");
            _control.dateValue(dateNull());
        }
    }
    return ret;
}
